package com.shopsphere;import java.util.*;import java.util.concurrent.ConcurrentHashMap;public interface InventoryRepository{Optional<Inventory> find(UUID productId);Inventory save(Inventory i);class InMemory implements InventoryRepository{private final Map<UUID,Inventory> data=new ConcurrentHashMap<>();public Optional<Inventory>find(UUID id){return Optional.ofNullable(data.get(id));}public Inventory save(Inventory i){data.put(i.productId(),i);return i;}}}
